"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import { useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { GlideHighlight, glideBox, type GlideBox } from "./glide-highlight";
import { cn } from "./lib/cn";
import "./button-group.css";

export function ButtonGroup({
  ref,
  className,
  children,
  ...props
}: ComponentProps<"div">) {
  const group = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => group.current!, []);
  const [box, setBox] = useState<GlideBox | null>(null);

  function place(target: EventTarget | null) {
    const button =
      target instanceof Element
        ? target.closest<HTMLElement>("[data-slot=button]")
        : null;
    if (!button || !group.current?.contains(button)) return;
    setBox(glideBox(button));
  }

  function rest(next: EventTarget | null) {
    const button =
      next instanceof Element
        ? next.closest<HTMLElement>("[data-slot=button]")
        : null;
    if (button && group.current?.contains(button)) return;
    setBox((current) => (current ? { ...current, active: false } : null));
  }

  return (
    <div
      {...props}
      ref={group}
      role="group"
      data-slot="button-group"
      onPointerMove={(event) => place(event.target)}
      onPointerLeave={() => rest(null)}
      onFocus={(event) => place(event.target)}
      onBlur={(event) => rest(event.relatedTarget)}
      className={cn(
        "relative inline-flex max-w-full items-stretch gap-0.5 rounded-touch bg-raised p-[3px] shadow-raised [&>[data-slot=button]]:h-[calc(var(--control-height)-6px)] [&>[data-slot=button]]:rounded-[9px] [&>[data-slot=button][data-size=icon]]:w-[calc(var(--control-height)-6px)]",
        className,
      )}
    >
      <GlideHighlight box={box} />
      {children}
    </div>
  );
}

"use client";

import { useLayoutEffect, useState } from "react";
import "./glide-highlight.css";

export type GlideBox = {
  active: boolean;
  left: number;
  top: number;
  width: number;
  height: number;
};

export function glideBox(target: HTMLElement): GlideBox {
  return {
    active: true,
    left: target.offsetLeft,
    top: target.offsetTop,
    width: target.offsetWidth,
    height: target.offsetHeight,
  };
}

export function useHighlightedGlide(
  root: HTMLElement | null,
  selector = "[data-highlighted]",
  /** Attributes whose change can move the target, e.g. data-state for an open trigger. */
  attributes: readonly string[] = ["data-highlighted"],
) {
  const [box, setBox] = useState<GlideBox | null>(null);

  useLayoutEffect(() => {
    const element = root;
    if (!element) return;
    const update = () => {
      const target = element.querySelector<HTMLElement>(selector);
      setBox((current) =>
        target ? glideBox(target) : current ? { ...current, active: false } : null,
      );
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(element, {
      subtree: true,
      attributes: true,
      attributeFilter: [...attributes],
    });
    return () => observer.disconnect();
    // The attribute list is fixed per call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, selector]);

  return box;
}

export function GlideHighlight({ box }: { box: GlideBox | null }) {
  if (!box) return null;
  return (
    <span
      aria-hidden="true"
      data-slot="glide-highlight"
      data-active={box.active}
      style={{
        width: box.width,
        height: box.height,
        transform: `translate(${box.left}px, ${box.top}px)`,
      }}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import {
  createContext,
  useContext,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
} from "react";
import { Button, type ButtonProps } from "./button";
import { ButtonGroup } from "./button-group";
import "./toggle.css";

export type ToggleProps = Omit<ButtonProps, "variant" | "aria-pressed"> & {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
};

/**
 * A button that stays pressed: bold, pin, mute. Pressed is recessed, the way a toggled tool
 * in a button group is, so "on" never looks like a selected tab. Give an icon-only toggle an
 * aria-label; the pressed state is announced by `aria-pressed`.
 */
export function Toggle({ pressed, defaultPressed = false, onPressedChange, onClick, ...props }: ToggleProps) {
  const [own, setOwn] = useState(defaultPressed);
  const on = pressed ?? own;
  return (
    <Button
      variant="ghost"
      {...props}
      data-toggle=""
      aria-pressed={on}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        if (pressed === undefined) setOwn(!on);
        onPressedChange?.(!on);
      }}
    />
  );
}

type GroupContext = {
  type: "single" | "multiple";
  values: string[];
  disabled?: boolean;
  toggle: (value: string) => void;
};
const Context = createContext<GroupContext | null>(null);

export type ToggleGroupProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "aria-label"> & {
  /** Single behaves like a radio group: one value, always one selected. Multiple lets any combination stay on. */
  type?: "single" | "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Names the group for assistive technology, such as "Text style". */
  label: string;
  disabled?: boolean;
};

/**
 * A row of toggles in the raised Button Group shell. The group is one tab stop; arrow keys,
 * Home and End move between items (and select, in single mode). Arrow keys follow the
 * reading direction, so the group works right to left.
 */
export function ToggleGroup({
  type = "multiple",
  value,
  defaultValue = [],
  onValueChange,
  label,
  disabled,
  onKeyDown,
  children,
  ...props
}: ToggleGroupProps) {
  const [own, setOwn] = useState(defaultValue);
  const values = value ?? own;
  const root = useRef<HTMLDivElement>(null);

  function set(next: string[]) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }
  function toggle(item: string) {
    if (type === "single") set([item]);
    else set(values.includes(item) ? values.filter((entry) => entry !== item) : [...values, item]);
  }

  const items = () => Array.from(root.current?.querySelectorAll<HTMLElement>('[data-slot="button"]:not(:disabled)') ?? []);
  // One tab stop: the item last focused, else the selected one, else the first. It lives on the
  // elements, so arrow keys and clicks can move it without re-rendering the group.
  const lastStop = useRef<HTMLElement | null>(null);
  useLayoutEffect(() => {
    const all = items();
    const stop =
      all.find((item) => item === lastStop.current) ??
      all.find((item) => item.getAttribute("aria-checked") === "true" || item.getAttribute("aria-pressed") === "true") ??
      all[0];
    for (const item of all) item.tabIndex = item === stop ? 0 : -1;
  });

  function keys(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || !root.current) return;
    const all = items();
    const at = all.indexOf(document.activeElement as HTMLElement);
    if (at < 0) return;
    const rtl = getComputedStyle(root.current).direction === "rtl";
    const forward = rtl ? "ArrowLeft" : "ArrowRight";
    const back = rtl ? "ArrowRight" : "ArrowLeft";
    let next: HTMLElement | undefined;
    if (event.key === forward || event.key === "ArrowDown") next = all[(at + 1) % all.length];
    else if (event.key === back || event.key === "ArrowUp") next = all[(at - 1 + all.length) % all.length];
    else if (event.key === "Home") next = all[0];
    else if (event.key === "End") next = all[all.length - 1];
    if (!next) return;
    event.preventDefault();
    lastStop.current = next;
    for (const item of all) item.tabIndex = item === next ? 0 : -1;
    next.focus();
    if (type === "single") next.click();
  }

  return (
    <Context.Provider value={{ type, values, disabled, toggle }}>
      <ButtonGroup
        ref={root}
        aria-label={label}
        onKeyDown={keys}
        onFocusCapture={(event) => {
          // A click or Tab landing on an item makes it the tab stop too.
          const target = event.target as HTMLElement;
          if (items().includes(target)) {
            lastStop.current = target;
            for (const item of items()) item.tabIndex = item === target ? 0 : -1;
          }
        }}
        {...props}
      >
        {children}
      </ButtonGroup>
    </Context.Provider>
  );
}

export type ToggleGroupItemProps = Omit<ButtonProps, "variant" | "value"> & { value: string };

export function ToggleGroupItem({ value, onClick, disabled, ...props }: ToggleGroupItemProps) {
  const group = useContext(Context);
  if (!group) throw new Error("ToggleGroupItem must be inside a ToggleGroup.");
  const on = group.values.includes(value);
  return (
    <Button
      variant="ghost"
      {...props}
      {...(group.type === "single" ? { role: "radio", "aria-checked": on } : { "aria-pressed": on })}
      disabled={group.disabled || disabled}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) group.toggle(value);
      }}
    />
  );
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
    box-shadow: inset 0 0 0 1px var(--border);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* button-group.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button-group"] > [data-slot="glide-highlight"] {
    top: 0;
    border-radius: 8px;
    transition:
      transform var(--duration-normal) var(--ease-out),
      width var(--duration-normal) var(--ease-out),
      height var(--duration-normal) var(--ease-out),
      opacity var(--duration-fast) var(--ease-out);
  }
}

/* glide-highlight.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="glide-highlight"] {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: var(--radius-surface);
    background: var(--muted);
    opacity: 0;
    transition:
      transform var(--duration-travel) var(--ease-showcase),
      width var(--duration-travel) var(--ease-showcase),
      height var(--duration-travel) var(--ease-showcase),
      opacity var(--duration-deliberate) var(--ease-out);
  }
  [data-slot="glide-highlight"][data-active="true"] {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="glide-highlight"] {
      transition: none;
    }
    [data-slot="glide-highlight"] {
      transition:
        transform 400ms var(--ease-showcase),
        width 400ms var(--ease-showcase),
        height 400ms var(--ease-showcase),
        opacity 280ms var(--ease-out);
    }
  }
}

/* toggle.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Toolbar group: one raised shell, transparent segments, one hover
     highlight. A toggled tool (aria-pressed) is recessed, the inverse of the
     segmented control's raised plate, so "on" never looks like "selected". */
  [data-slot="button-group"] > [data-slot="button"] {
    position: relative;
    z-index: 1;
    --b-bg: transparent;
    --b-bg-hover: transparent;
    --b-bg-press: var(--muted);
    --b-fg: var(--foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  [data-slot="button-group"] > [data-slot="button"][aria-pressed="true"],
  [data-slot="button-group"] > [data-slot="button"][aria-checked="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}
